package ir
import("crypto/sha256";"encoding/hex";"encoding/json";"strings";"testing")
func attachedInput(t *testing.T) Message {t.Helper();s:="safe original α [opaque-ref]";h:=sha256.Sum256([]byte(s));return Message{Role:"user",Blocks:[]Block{{Type:"text",Text:&s,InputAttachment:&InputAttachment{1,"host.original-input.v1","12345678-1234-4234-8234-123456789abc",hex.EncodeToString(h[:]),"  {\"wide\":9007199254740993,\"opaque\":\"CANARY\"}\n"}}}}}
func cloneInput(t *testing.T,m Message) Message{t.Helper();b,_:=json.Marshal(m);var n Message;if !Decode(b,&n)||!ValidMessage(b){t.Fatal("decode")};return n}
func TestInputAttachmentExactRoundTripAndCheckpoint(t *testing.T){m:=attachedInput(t);raw,_:=json.Marshal(m);n:=cloneInput(t,m);again,_:=json.Marshal(n);if string(raw)!=string(again)||!InputAttachmentsPreserved([]Message{m},[]Message{n}){t.Fatal("lost exact source bytes")};if n.Blocks[0].InputAttachment.Opaque!=m.Blocks[0].InputAttachment.Opaque{t.Fatal("wide/whitespace opaque changed")};for _,mutate:=range []func(*Message){func(n *Message){n.Blocks[0].InputAttachment=nil},func(n *Message){n.Blocks[0].InputAttachment.Opaque+="changed"},func(n *Message){*n.Blocks[0].Text+="changed"},func(n *Message){n.Blocks[0].InputAttachment.OperationUUID="22345678-1234-4234-8234-123456789abc"}}{n:=cloneInput(t,m);mutate(&n);if InputAttachmentsPreserved([]Message{m},[]Message{n}){t.Fatal("changed checkpoint admitted")}};if InputAttachmentsPreserved([]Message{m},nil)||InputAttachmentsPreserved(nil,[]Message{m})||InputAttachmentsPreserved([]Message{m},[]Message{m,m}){t.Fatal("drop/mint/duplicate accepted")}}
func TestInputAttachmentClosedShapeAndUserTextOnly(t *testing.T){m:=attachedInput(t);for _,change:=range []func(*Message){func(n *Message){n.Role="assistant"},func(n *Message){n.Blocks[0].Type="thinking"},func(n *Message){n.Blocks[0].InputAttachment.SchemaVersion=2},func(n *Message){n.Blocks[0].InputAttachment.Kind="other"},func(n *Message){n.Blocks[0].InputAttachment.Opaque=strings.Repeat("x",262145)},func(n *Message){n.Blocks[0].InputAttachment.Opaque="a\x00b"},func(n *Message){*n.Blocks[0].Text+="changed"}}{n:=cloneInput(t,m);change(&n);raw,_:=json.Marshal(n);if ValidMessage(raw){t.Fatal("bad source admitted")}};raw,_:=json.Marshal(m);bad:=strings.Replace(string(raw),`"input_attachment":{`,`"input_attachment":null,"input_attachment":{`,1);if ValidMessage([]byte(bad)){t.Fatal("duplicate admitted")};bad=strings.Replace(string(raw),`"input_attachment":{`,`"input_attachment":{"extra":1,`,1);if ValidMessage([]byte(bad)){t.Fatal("extra admitted")}}
